widget.solution:
import numpy as np
import pandas as pd
from math import exp

# mid(df) is loaded, and clean = clean_quotes(make_chain()).

def implied_forward(df_T, r, T):
    """Median over strikes of K + e^(rT) (C - P); NaN under 3 pairs."""
    w = df_T.assign(mid=mid(df_T)).pivot(index="strike", columns="type", values="mid")
    w = w.reindex(columns=["call", "put"]).dropna()
    if len(w) < 3:
        return float("nan")
    F = w.index + exp(r * T) * (w["call"] - w["put"])
    return float(np.median(F))

